pragma solidity >=0.8.0;

import {BlastYields} from "/blast/libraries/BlastYields.sol";
import {OperatableV2} from "mixins/OperatableV2.sol";

contract BlastGovernor is OperatableV2 {
    event LogFeeToChanged(address indexed feeTo);
    error ErrZeroAddress();

    address public feeTo;

    receive() external payable {}

    constructor(address feeTo_, address _owner) OperatableV2(_owner) {
        if (feeTo_ == address(0)) {
            revert ErrZeroAddress();
        }

        feeTo = feeTo_;
        BlastYields.configureDefaultClaimables(address(this));
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// OPERATORS
    //////////////////////////////////////////////////////////////////////////////////////

    function claimNativeYields(address contractAddress) external onlyOperators returns (uint256) {
        return BlastYields.claimAllNativeYields(contractAddress, feeTo);
    }

    function claimMaxGasYields(address contractAddress) external onlyOperators returns (uint256) {
        return BlastYields.claimMaxGasYields(contractAddress, feeTo);
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// ADMIN
    //////////////////////////////////////////////////////////////////////////////////////

    function setFeeTo(address _feeTo) external onlyOwner {
        if(_feeTo == address(0)) {
            revert ErrZeroAddress();
        }

        feeTo = _feeTo;
        emit LogFeeToChanged(_feeTo);
    }

    function callBlastPrecompile(bytes calldata data) external onlyOwner {
        BlastYields.callPrecompile(data);
    }

    function execute(address to, uint256 value, bytes calldata data) external onlyOwner returns (bool success, bytes memory result) {
        (success, result) = to.call{value: value}(data);
    }
}
"},"src/blast/BlastMagicLP.sol":{"content":"// SPDX-License-Identifier: UNLICENSED

pragma solidity >=0.8.0;

import {MagicLP} from "/mimswap/MagicLP.sol";
import {BlastYields} from "/blast/libraries/BlastYields.sol";
import {BlastPoints} from "/blast/libraries/BlastPoints.sol";
import {BlastTokenRegistry} from "/blast/BlastTokenRegistry.sol";

contract BlastMagicLP is MagicLP {
    event LogFeeToChanged(address indexed feeTo);
    event LogOperatorChanged(address indexed, bool);
    event LogYieldClaimed(uint256 gasAmount, uint256 nativeAmount, uint256 token0Amount, uint256 token1Amount);

    error ErrNotAllowedImplementationOperator();

    BlastTokenRegistry public immutable registry;

    /// @dev Implementation storage
    address public feeTo;
    mapping(address => bool) public operators;

    constructor(BlastTokenRegistry registry_, address feeTo_, address owner_) MagicLP(owner_) {
        if (feeTo_ == address(0)) {
            revert ErrZeroAddress();
        }
        if (address(registry_) == address(0)) {
            revert ErrZeroAddress();
        }

        registry = registry_;
        feeTo = feeTo_;
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// VIEWS
    //////////////////////////////////////////////////////////////////////////////////////

    function version() external pure override returns (string memory) {
        return "BlastMagicLP 1.0.0";
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// OPERATORS / CLONES ONLY
    //////////////////////////////////////////////////////////////////////////////////////

    function claimGasYields() external onlyClones onlyImplementationOperators returns (uint256) {
        address feeTo_ = BlastMagicLP(address(implementation)).feeTo();

        return BlastYields.claimMaxGasYields(feeTo_);
    }

    function claimTokenYields() external onlyClones onlyImplementationOperators returns (uint256 token0Amount, uint256 token1Amount) {
        address feeTo_ = BlastMagicLP(address(implementation)).feeTo();

        if (registry.nativeYieldTokens(_BASE_TOKEN_)) {
            token0Amount = BlastYields.claimAllTokenYields(_BASE_TOKEN_, feeTo_);
        }
        if (registry.nativeYieldTokens(_QUOTE_TOKEN_)) {
            token1Amount = BlastYields.claimAllTokenYields(_QUOTE_TOKEN_, feeTo_);
        }
    }

    function updateTokenClaimables() external onlyClones onlyImplementationOperators {
        _updateTokenClaimables();
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// ADMIN / CLONES ONLY
    //////////////////////////////////////////////////////////////////////////////////////

    function callBlastPrecompile(bytes calldata data) external onlyClones onlyImplementationOwner {
        BlastYields.callPrecompile(data);
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// ADMIN / IMPLEMENTATION ONLY
    //////////////////////////////////////////////////////////////////////////////////////

    function setFeeTo(address feeTo_) external onlyImplementation onlyImplementationOwner {
        if (feeTo_ == address(0)) {
            revert ErrZeroAddress();
        }

        feeTo = feeTo_;
        emit LogFeeToChanged(feeTo_);
    }

    function setOperator(address operator, bool status) external onlyImplementation onlyImplementationOwner {
        operators[operator] = status;
        emit LogOperatorChanged(operator, status);
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// INTERNALS
    //////////////////////////////////////////////////////////////////////////////////////

    function _afterInitialized() internal override {
        BlastYields.configureDefaultClaimables(address(this));
        BlastPoints.configure();
        _updateTokenClaimables();
    }

    function _updateTokenClaimables() internal {
        if (registry.nativeYieldTokens(_BASE_TOKEN_)) {
            BlastYields.enableTokenClaimable(_BASE_TOKEN_);
        }

        if (registry.nativeYieldTokens(_QUOTE_TOKEN_)) {
            BlastYields.enableTokenClaimable(_QUOTE_TOKEN_);
        }
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// MODIFIERS
    //////////////////////////////////////////////////////////////////////////////////////

    modifier onlyImplementationOperators() {
        if (!BlastMagicLP(address(implementation)).operators(msg.sender) && msg.sender != implementation.owner()) {
            revert ErrNotAllowedImplementationOperator();
        }
        _;
    }
}
"},"src/blast/BlastOnboarding.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity >=0.8.0;

import {Owned} from "solmate/auth/Owned.sol";
import {BlastYields} from "/blast/libraries/BlastYields.sol";
import {BlastTokenRegistry} from "/blast/BlastTokenRegistry.sol";
import {Proxy} from "openzeppelin-contracts/proxy/Proxy.sol";
import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";
import {BlastPoints} from "/blast/libraries/BlastPoints.sol";
import {Pausable} from "openzeppelin-contracts/security/Pausable.sol";

contract BlastOnboardingData is Owned, Pausable {
    error ErrZeroAddress();
    error ErrWrongState();
    error ErrUnsupportedToken();
    error ErrNotAllowed();

    enum State {
        Idle,
        Opened,
        Closed
    }

    struct Balances {
        uint256 unlocked;
        uint256 locked;
        uint256 total;
    }

    State public state;
    address public bootstrapper;
    address public feeTo;
    BlastTokenRegistry public registry;

    // Global
    mapping(address token => bool) public supportedTokens;
    mapping(address token => Balances) public totals;
    mapping(address token => uint256 cap) public caps;

    // Per-user
    mapping(address user => mapping(address token => Balances)) public balances;

    modifier onlyState(State _state) {
        if (state != _state) {
            revert ErrWrongState();
        }
        _;
    }

    modifier onlySupportedTokens(address token) {
        if (!supportedTokens[token]) {
            revert ErrUnsupportedToken();
        }

        _;
    }

    constructor() Owned(msg.sender) {
        BlastYields.configureDefaultClaimables(address(this));
        BlastPoints.configure();
    }
}

contract BlastOnboarding is BlastOnboardingData, Proxy {
    using SafeTransferLib for address;

    event LogBootstrapperChanged(address indexed bootstrapper);
    event LogTokenSupported(address indexed token, bool supported);
    event LogDeposit(address indexed user, address indexed token, uint256 amount, bool lock);
    event LogLock(address indexed user, address indexed token, uint256 amount);
    event LogFeeToChanged(address indexed feeTo);
    event LogWithdraw(address indexed user, address indexed token, uint256 amount);
    event LogTokenCapChanged(address indexed token, uint256 cap);
    event LogStateChange(State state);
    event LogTokenRescue(address indexed token, address indexed to, uint256 amount);

    error ErrUnsupported();
    error ErrCapReached();

    receive() external payable override {
        revert ErrUnsupported();
    }

    constructor(BlastTokenRegistry registry_, address feeTo_) {
        if (address(registry_) == address(0)) {
            revert ErrZeroAddress();
        }

        if (feeTo_ == address(0)) {
            revert ErrZeroAddress();
        }

        registry = registry_;
        feeTo = feeTo_;
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// PUBLIC
    //////////////////////////////////////////////////////////////////////////////////////

    function deposit(address token, uint256 amount, bool lock_) external whenNotPaused onlyState(State.Opened) onlySupportedTokens(token) {
        token.safeTransferFrom(msg.sender, address(this), amount);

        if (lock_) {
            totals[token].locked += amount;
            balances[msg.sender][token].locked += amount;
        } else {
            totals[token].unlocked += amount;
            balances[msg.sender][token].unlocked += amount;
        }

        totals[token].total += amount;

        if (caps[token] > 0 && totals[token].total > caps[token]) {
            revert ErrCapReached();
        }

        balances[msg.sender][token].total += amount;

        emit LogDeposit(msg.sender, token, amount, lock_);
    }

    function lock(address token, uint256 amount) external whenNotPaused onlyState(State.Opened) onlySupportedTokens(token) {
        balances[msg.sender][token].unlocked -= amount;
        balances[msg.sender][token].locked += amount;
        totals[token].unlocked -= amount;
        totals[token].locked += amount;

        emit LogLock(msg.sender, token, amount);
    }

    function withdraw(address token, uint256 amount) external whenNotPaused onlySupportedTokens(token) {
        balances[msg.sender][token].unlocked -= amount;
        balances[msg.sender][token].total -= amount;
        totals[token].unlocked -= amount;
        totals[token].total -= amount;

        token.safeTransfer(msg.sender, amount);

        emit LogWithdraw(msg.sender, token, amount);
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// ADMIN
    //////////////////////////////////////////////////////////////////////////////////////

    function setFeeTo(address feeTo_) external onlyOwner {
        if (feeTo_ == address(0)) {
            revert ErrZeroAddress();
        }

        feeTo = feeTo_;
        emit LogFeeToChanged(feeTo_);
    }

    function callBlastPrecompile(bytes calldata data) external onlyOwner {
        BlastYields.callPrecompile(data);
    }

    function claimGasYields() external onlyOwner returns (uint256) {
        return BlastYields.claimMaxGasYields(feeTo);
    }

    function claimTokenYields(address[] memory tokens) external onlyOwner {
        for (uint256 i = 0; i < tokens.length; i++) {
            if (!supportedTokens[tokens[i]]) {
                revert ErrUnsupportedToken();
            }
            if (registry.nativeYieldTokens(tokens[i])) {
                BlastYields.claimAllTokenYields(tokens[i], feeTo);
            }
        }
    }

    function setTokenSupported(address token, bool supported) external onlyOwner {
        supportedTokens[token] = supported;

        if (registry.nativeYieldTokens(token)) {
            BlastYields.enableTokenClaimable(token);
        }

        emit LogTokenSupported(token, supported);
    }

    function setCap(address token, uint256 cap) external onlyOwner onlySupportedTokens(token) {
        caps[token] = cap;
        emit LogTokenCapChanged(token, cap);
    }

    function setBootstrapper(address bootstrapper_) external onlyOwner {
        bootstrapper = bootstrapper_;
        emit LogBootstrapperChanged(bootstrapper_);
    }

    function open() external onlyOwner onlyState(State.Idle) {
        state = State.Opened;
        emit LogStateChange(State.Opened);
    }

    function close() external onlyOwner onlyState(State.Opened) {
        state = State.Closed;
        emit LogStateChange(State.Closed);
    }

    function rescue(address token, address to, uint256 amount) external onlyOwner {
        if (supportedTokens[token]) {
            revert ErrNotAllowed();
        }

        token.safeTransfer(to, amount);
        emit LogTokenRescue(token, to, amount);
    }

    function pause() external onlyOwner {
        _pause();
    }

    function unpause() external onlyOwner {
        _unpause();
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// PROXY IMPLEMENTATION
    //////////////////////////////////////////////////////////////////////////////////////

    function _implementation() internal view override returns (address) {
        return address(bootstrapper);
    }
}
"},"src/blast/BlastOnboardingBoot.sol":{"content":"// SPDX-License-Identifier: UNLICENSED
pragma solidity >=0.8.0;

import {BlastOnboarding} from "/blast/BlastOnboarding.sol";
import {BlastOnboardingData} from "/blast/BlastOnboarding.sol";
import {Router} from "/mimswap/periphery/Router.sol";
import {IFeeRateModel} from "/mimswap/interfaces/IFeeRateModel.sol";
import {IFactory} from "/mimswap/interfaces/IFactory.sol";
import {SafeTransferLib} from "solady/utils/SafeTransferLib.sol";
import {DecimalMath} from "/mimswap/libraries/DecimalMath.sol";
import {LockingMultiRewards} from "staking/LockingMultiRewards.sol";

address constant USDB = 0x4300000000000000000000000000000000000003;
address constant MIM = 0x76DA31D7C9CbEAE102aff34D3398bC450c8374c1;
uint256 constant FEE_RATE = 0.0005 ether; // 0.05%
uint256 constant K = 0.00025 ether; // 0.00025, 1.25% price fluctuation, similar to A2000 in curve
uint256 constant I = 0.998 ether; // 1 MIM = 0.998 USDB
uint256 constant USDB_TO_MIN = 1.002 ether; // 1 USDB = 1.002 MIM
uint256 constant MIM_TO_MIN = I;

// Add a new data contract each bootstrap upgrade that involves
// adding new storage variables.
contract BlastOnboardingBootDataV1 is BlastOnboardingData {
    address public pool;
    Router public router;
    IFactory public factory;
    uint256 public totalPoolShares;
    bool public ready;
    LockingMultiRewards public staking;
    mapping(address user => bool claimed) public claimed;
}

/// @dev Functions are postfixed with the version number to avoid collisions
contract BlastOnboardingBoot is BlastOnboardingBootDataV1 {
    using SafeTransferLib for address;

    event LogReadyChanged(bool ready);
    event LogClaimed(address indexed user, uint256 shares, bool lock);
    event LogInitialized(Router indexed router);
    event LogLiquidityBootstrapped(address indexed pool, address indexed staking, uint256 amountOut);
    event LogStakingChanged(address indexed staking);

    error ErrInsufficientAmountOut();
    error ErrNotReady();
    error ErrAlreadyClaimed();
    error ErrWrongFeeRateModel();
    error ErrAlreadyBootstrapped();
    error ErrNothingToClaim();
    error ErrCannotChangeOnceReady();

    //////////////////////////////////////////////////////////////////////////////////////
    /// PUBLIC
    //////////////////////////////////////////////////////////////////////////////////////

    function claim(bool lock) external returns (uint256 shares) {
        if (!ready) {
            revert ErrNotReady();
        }
        if (claimed[msg.sender]) {
            revert ErrAlreadyClaimed();
        }

        shares = _claimable(msg.sender);
        if (shares == 0) {
            revert ErrNothingToClaim();
        }

        claimed[msg.sender] = true;
        staking.stakeFor(msg.sender, shares, lock);

        emit LogClaimed(msg.sender, shares, lock);
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// VIEWS
    //////////////////////////////////////////////////////////////////////////////////////

    function claimable(address user) external view returns (uint256 shares) {
        if (!ready || claimed[user]) {
            return 0;
        }

        return _claimable(user);
    }

    function previewTotalPoolShares() external view returns (uint256 baseAdjustedInAmount, uint256 quoteAdjustedInAmount, uint256 shares) {
        uint256 baseAmount = totals[MIM].locked;
        uint256 quoteAmount = totals[USDB].locked;
        return router.previewCreatePool(I, baseAmount, quoteAmount);
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// ADMIN
    //////////////////////////////////////////////////////////////////////////////////////

    function bootstrap(uint256 minAmountOut) external onlyOwner onlyState(State.Closed) returns (address, address, uint256) {
        if (pool != address(0)) {
            revert ErrAlreadyBootstrapped();
        }

        uint256 baseAmount = totals[MIM].locked;
        uint256 quoteAmount = totals[USDB].locked;
        MIM.safeApprove(address(router), type(uint256).max);
        USDB.safeApprove(address(router), type(uint256).max);

        (pool, totalPoolShares) = router.createPool(MIM, USDB, FEE_RATE, I, K, address(this), baseAmount, quoteAmount);

        if (totalPoolShares < minAmountOut) {
            revert ErrInsufficientAmountOut();
        }

        // Create staking contract
        // 3x boosting for locker, 7 days reward duration, 13 weeks lp locking
        // make this contract temporary the owner the set it as an operator
        // for permissionned `stakeFor` during the claiming process and then
        // transfer the ownership to the onboarding owner.
        staking = new LockingMultiRewards(pool, 30_000, 7 days, 13 weeks, address(this));
        staking.setOperator(address(this), true);
        staking.transferOwnership(owner);

        // Approve staking contract
        pool.safeApprove(address(staking), totalPoolShares);

        emit LogLiquidityBootstrapped(pool, address(staking), totalPoolShares);

        return (pool, address(staking), totalPoolShares);
    }

    function initialize(Router _router) external onlyOwner {
        router = Router(payable(_router));
        factory = IFactory(router.factory());
        emit LogInitialized(_router);
    }

    // Just in case we need to change the staking contract after
    // the automatic bootstrapping process
    function setStaking(LockingMultiRewards _staking) external onlyOwner {
        if (ready) {
            revert ErrCannotChangeOnceReady();
        }

        staking = _staking;
        emit LogStakingChanged(address(_staking));
    }

    function setReady(bool _ready) external onlyOwner onlyState(State.Closed) {
        ready = _ready;
        emit LogReadyChanged(ready);
    }

    //////////////////////////////////////////////////////////////////////////////////////
    /// INTERNALS
    //////////////////////////////////////////////////////////////////////////////////////

    function _claimable(address user) internal view returns (uint256 shares) {
        uint256 totalLocked = totals[MIM].locked + totals[USDB].locked;

        if (totalLocked == 0) {
            return 0;
        }

        uint256 userLocked = balances[user][MIM].locked + balances[user][USDB].locked;
        return (userLocked * totalPoolShares) / totalLocked;
    }
}
